INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8440, '我们与联盟的冲突已升级为真正的战争。到这一步，双方都不再需要、也不再期待以虚假的借口开战了。$B$B阿拉希盆地的战斗，说白了就是一场资源之争。资源要么被联盟夺走用来对付我们，要么被我们夺来支撑战争。帮助污染者维持我们所需的资源供给，$N！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Our conflict with the Alliance has escalated to a true war. No longer are false pretenses 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8441, '我们与联盟的冲突已升级为真正的战争。到这一步，双方都不再需要、也不再期待以虚假的借口开战了。$B$B阿拉希盆地的战斗，说白了就是一场资源之争。资源要么被联盟夺走用来对付我们，要么被我们夺来支撑战争。帮助污染者维持我们所需的资源供给，$N！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- Our conflict with the Alliance has escalated to a true war. No longer are false pretenses 
